style.css:
/* Vintage Rose */
body { background: #F2E4DC !important; color: #594044 !important; }
h1, h2, h3 { color: #A85F70 !important; }
p { color: #785B5D !important; }
a { color: #B76E79 !important; }
button {
  background: #D8A0A8 !important;
  color: #492F36 !important;
  border: 1px solid #B76E79 !important;
  border-radius: 6px !important;
}
input, textarea {
  background: #E8C8C5 !important;
  color: #594044 !important;
  border: 1px solid #C38C94 !important;
}
::selection { background: #B76E79; color: white; }
